# Group 4 Cortech tabs, batch 1 (Nov 17). Loaded by mc6.py after ../pc.py, ../g2/pc2.py, ../g3/pc3.py, ../g4/pc4.py, ../g5/pc5.py (constants).
# Andrew's standing rules applied: no "with hardware of your choice" (install ends "Hardware not included"), "do not use loose sand", collection links only.
P=[]
def add(**k): P.append(k)
SEATC=CP+'furniture/seating/'
SUMC=CP+'furniture/endurance/'
BEDC=CP+'furniture/beds/'
HOOKC=CP+'facility-maintenance/ligature-resistant-hooks/'
PSB='https://www.anchortex.com/collections/bh-patient-safety-beds'
BED_COLL=f"Explore Anchortex's [Behavioral Healthcare Anti-Ligature Furniture]({BH}) and [Patient Safety Beds and Bed Restraints]({PSB}) collections for more beds and patient room furniture."
HOOK_COLL=f"Explore Anchortex's [Hardware for Behavioral Health Care Facilities]({HWB}) and [Prison & Detention Hardware & Equipment]({HWC}) collections for more ligature resistant hardware."
SEAT_SERIES=[
('h3','[H2] About Cortech Seating'),
('p','Cortech molded seating is designed for dayrooms, lounges, dining areas, and patient rooms in behavioral healthcare and correctional facilities, where chairs are used hard every day and must be difficult to break or tamper with.'),
('p','Cortech molded seating includes:'),
('b1','**Stacking Chairs:** The Razorback injection molded stack chair'),
('b1','**Lounge and Group Seating:** Sabre and Sentinel Chairs stand alone or bolt together. The Endurance, Sync, and Summit collections include guest chairs, accent chairs and tables, lounge chairs, and benches.'),
('b1','**Rocking Chairs:** The Radial Rocker'),
]
SUMMIT_SERIES=[
('h3','[H2] About Cortech Summit Series'),
('p','The Cortech Summit Series is a line of molded seating and tables with a calm, residential look, made for behavioral healthcare facilities and other secure settings. Most Summit seating comes in a standard molded finish or with a Veldura soft-touch exterior.'),
('p','The Summit Series includes:'),
('b1','**Chairs:** Guest Chair (300 / 301), Accent Chair (310 / 311), and Lounge Chair (320 / 321)'),
('b1','**Stools:** Summit Stool (330 / 331)'),
('b1','**Tables:** Side Table (342 / 343), Mid-Range Table (353 / 354), and All Purpose Table (361 / 363 / 364)'),
]
BED_SERIES=[
('h3','[H2] About Cortech Beds'),
('p','Cortech beds are rotationally molded in one piece for patient rooms in behavioral healthcare facilities and cells in correctional facilities, where beds must be safe, strong, and easy to clean.'),
('p','Cortech beds include:'),
('b1','**Solstice Series:** The Solstice Bed, and the Solstice Safeguard Bed with raised side panels for fall-risk patients'),
('b1','**Sequoia Series:** Molded beds and night stands with a wood grain finish'),
('b1','**Endurance Series:** Endurance beds, wall mounted bunks, and EZ Bunk stackable temporary sleep surfaces'),
]
HOOK_SERIES=[
('h3','[H2] About Cortech HookMax Ligature Resistant Hooks'),
('p','Cortech HookMax hooks hold clothing and towels, but bend and release when extra force is applied, so a ligature slides off. After release, the hook returns to its shape and keeps working. They suit resident rooms, bathrooms, and common areas in behavioral healthcare and correctional facilities.'),
('p','The HookMax line includes:'),
('b1','**HookMax:** Releases at a maximum 10 lb load'),
('b1','**HookMax+:** Releases at a maximum 20 lb load'),
]
SER_SEAT='Series section: "About Cortech Seating" is a new section for the Razorback, Sabre, Sentinel, and Radial Rocker pages. It is the same on each of these pages.'
SER_SUM='Series section: "About Cortech Summit Series" is a new section for the Summit chairs, stools, and tables. It is the same on each Summit page.'
SER_BED='Series section: "About Cortech Beds" is a new section for the Solstice and Sequoia bed pages. It is the same on each of these pages.'
SER_HOOK='Series section: "About Cortech HookMax Ligature Resistant Hooks" is a new section for the HookMax and HookMax+ pages. It is the same on both pages.'
GGW='**Environmental Certification:** GREENGUARD Gold'
SEAT_APPS=['Dayrooms, lounges, and waiting areas in behavioral healthcare facilities and psychiatric hospitals','Dayrooms, visitation rooms, and common areas in correctional facilities and jails','Residential treatment centers and other group spaces']
BALL_DOOR=lambda m:f'**Ballast Door:** The {m}S has a ballast door for adding sandbags on site; it closes with tamper-resistant screws. Do not use loose sand'
SEAT_INST=['**Floor Mounting:** Bolt to the floor through concealed pilot holes; see Cortech instructions. Hardware not included',
 '**Ganging:** Bolt chairs together with 3/8”-16×2½” security Torx bolts and flat washers; see Cortech instructions. Hardware not included']
def outn(what): return f'Outdoor use: the FAQ on the Cortech product page says {what} rated for outdoor use and UV stabilized, so I added it to the description.'
def chart12(n): return (f'Product images: the page has {n} images. The last one is the older Cortech color chart with 12 colors. The Cortech product page has photos of this chair in all 18 colors. '
  'Would you like me to add them, and replace the chart with the 18-color chart?')
GG_WEB='GREENGUARD Gold: this comes from the Cortech web page. The spec sheet does not mention it.'

# 1. Razorback 86484
add(tab='86484 - Cortech Razorback Stackable Chair',short='86484: Cortech Razorback Stackable Chair',
 handle='cortech-86484-razorback-stackable-chair',src=[SEATC+'razorback-chair/'],
 specs=[('86484',CU+'Razorback-Chair-Spec-Sheet.pdf')],
 h1='Cortech Razorback Stackable Chair – 86484',
 cur_h1='Cortech Razorback - Stackable Chair - High‑Strength Rotationally Molded Polypropylene - Model 86484',
 sub='Virtually Unbreakable One-Piece Molded Stack Chair with Muscle-Back Legs, Rated for Outdoor Use',
 cur_sub='Cortech USA 86484BK, 86484B, 86484FG, 86484T, 86484SB, 86484P, 86484BG, 86484GN, 86884BN Razorback Stackable Chair',
 intro=['The **Cortech Razorback Stackable Chair** is a virtually unbreakable stack chair for dayrooms, dining areas, classrooms, and group rooms in behavioral healthcare and correctional facilities. Its low back and Muscle-Back legs make it harder to rock and tip over, and the chairs stack for storage.',
  'The chair is injection molded in one piece from high impact “no break” polypropylene, with no steel or wood components. It weighs just over 8 lbs, has a 1,500 lb static load, and its legs have a bolt-down option. The Razorback is rated for indoor or outdoor use.'],
 bullets=['**Material:** One-piece injection molded high impact “no break” polypropylene; no steel or wood components',
  '**Dimensions:** 21”W×21”D×30”H',
  '**Weight:** 8.25 lbs',
  '**Static Load:** 1,500 lbs (ANSI/BIFMA X5.1-2011)',
  '**Stacking:** Stack 8 to 10 chairs on a dolly, or as high as you can comfortably reach without one; chair dolly sold separately',
  '**Legs:** Muscle-Back legs reduce rocking and tipping and include a bolt-down option',
  '**Testing:** Passes ASTM F1561-03',
  FLAME2,
  '**Outdoor Use:** Suitable for indoor or outdoor use; resists UV exposure and moisture',
  '**Easy Cleaning:** Easy to clean with a damp cloth; resistant to stains',
  '**Colors:** Black, Blue Gray, Brown, Buff, Fog Gray, Green, Plum, Slate Blue, or Teal (custom colors available on request)',
  LIFE,ISO],
 models=['**86484 – Razorback Stackable Chair:** 21”W×21”D×30”H, 8.25 lbs'],
 install=['**Floor Mounting:** Optional; the Muscle-Back legs have a pilot hole for field drilling to bolt the chair down. Hardware not included'],
 apps=apps('The Razorback suits rooms that need light, stackable chairs that are hard to break, rock, or tip.',
  ['Dayrooms, dining areas, and visitation rooms in correctional facilities and jails','Group rooms and activity rooms in behavioral healthcare facilities and psychiatric hospitals','Schools, shelters, and other intense use settings'],END_COLL),
 series=SEAT_SERIES,
 mt='Cortech Razorback Stackable Chair - 86484 at Anchortex',
 md='Shop the Cortech Razorback Stackable Chair, a virtually unbreakable one-piece molded stack chair with Muscle-Back legs, rated for indoor or outdoor use.',
 notes=[SER_SEAT,
  'H1: I took out "High-Strength Rotationally Molded Polypropylene" and "Model." The Cortech spec sheet says the Razorback is injection molded, not rotationally molded.',
  'Weight: your variant is set to 255 lbs, which looks like a placeholder. The Cortech spec sheet says 8.25 lbs, so I used that.',
  W10,
  'Stacking: the Cortech spec sheet says to stack 8 to 10 chairs on a dolly. The FAQ on the Cortech web page says 20 chairs stack to about 7 feet. I used the spec sheet.',
  'Chair dolly: your current page names the dolly DY9000. The Cortech spec sheet does not give a model number, so I wrote "chair dolly sold separately."',
  'Floor mounting: the Cortech spec sheet says the Muscle-Back legs include a bolt-down option. The pilot hole for field drilling comes from your current page.',
  'Outdoor use: the FAQ on the Cortech product page says the Razorback resists UV exposure and moisture and is suitable for indoor or outdoor use, so I added it to the description.',
  'Colors: your current page lists the same 9 colors as the Cortech spec sheet, but the Brown code is written "86884BN." The Cortech code is 86484BN.',
  'I left out "Cost effective economical," since it is a marketing claim.',
  'Product images: the page has three images, including a color chart with the 9 Razorback colors. The Cortech product page has photos of the Razorback in all 9 colors. Would you like me to add them?'])

